```python
from flask import Flask, request, render_template, redirect, url_for
from flask_sqlalchemy import SQLAlchemy
import re

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///globalbank.db'  # Or your preferred database connection string
db = SQLAlchemy(app)

class Account(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    account_number = db.Column(db.String(10), unique=True, nullable=False)

    def __repr__(self):
        return f'<Account {self.account_number}>'

@app.route('/account/transferFunds', methods=['POST'])
def transfer_funds():
    from_account = request.form['fromAccount']
    to_account = request.form['toAccount']
    amount = request.form['amount']

    if not validate_account(from_account) or not validate_account(to_account):
        return "Invalid account numbers", 400

    if not validate_amount(amount):
        return "Invalid amount", 400

    # Perform the actual fund transfer, updating both accounts' balances in the database
    # ...

    return "Funds transferred successfully", 200

def validate_account(account):
    regex = re.compile(r'^\d{10}$')
    return bool(regex.match(account))

def validate_amount(amount):
    try:
        amount_value = float(amount)
        return amount_value > 0
    except ValueError:
        return False
```

